(function(){
  CardSpoke_MODS.register('field-notes-expansion', {
    meta: {
      name: 'Field Notes Expansion',
      type: 'Expansion',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Adds a lightweight journal ribbon and geo pins for research logs',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onAppInit(ctx){
      const ribbon = document.createElement('div');
      ribbon.className = 'fn-ribbon';
      ribbon.textContent = 'Field log ready';
      document.body.appendChild(ribbon);
    },
    onCardRender(ctx, card, el){
      if(!el) return;
      const pin = document.createElement('span');
      pin.className = 'fn-pin';
      pin.textContent = '⟁';
      const header = el.querySelector('.card-title') || el;
      header.prepend(pin);
    },
    onDisable(){
      document.querySelectorAll('.fn-ribbon').forEach(n => n.remove());
      document.querySelectorAll('.fn-pin').forEach(n => n.remove());
    }
  });
})();
